import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import PageStructure from 'flarum/forum/components/PageStructure';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import fullTime from 'flarum/common/helpers/fullTime';
import CollectionView from './CollectionView';
import FirstFinishers from './FirstFinishers';

/**
 * A Hunt's public page: what it is, how far the member has got, and who finished first.
 */
export default class HuntPage extends Page {
  hunt = null;
  notFound = false;
  finishers = [];
  moreFinishers = false;
  loadingFinishers = false;
  oninit(vnode) {
    super.oninit(vnode);
    app.store.find('scavenger-hunts', m.route.param('slug'), {
      include: 'parts'
    }).then(hunt => {
      this.hunt = hunt;
      app.setTitle(hunt.title());
      this.loadFinishers();
    }).catch(() => {
      this.notFound = true;
      m.redraw();
    });
  }
  view() {
    return m(PageStructure, {
      className: "HuntPage",
      hero: () => this.hero(),
      sidebar: () => m(IndexSidebar, null),
      loading: !this.hunt && !this.notFound
    }, this.content());
  }
  hero() {
    const hunt = this.hunt;
    if (!hunt) return null;
    return m("header", {
      className: "Hero HuntPage-hero"
    }, m("div", {
      className: "container"
    }, m("h1", {
      className: "Hero-title"
    }, hunt.title()), hunt.description() && m("div", {
      className: "Hero-subtitle"
    }, hunt.description()), m("div", {
      className: "HuntPage-schedule"
    }, hunt.startsAt() && m("span", null, app.translator.trans('fof-scavenger-hunt.forum.hunt_page.starts', {
      time: fullTime(hunt.startsAt())
    })), hunt.endsAt() && m("span", null, app.translator.trans('fof-scavenger-hunt.forum.hunt_page.ends', {
      time: fullTime(hunt.endsAt())
    })), !hunt.isActive() && m("span", {
      className: "HuntPage-ended"
    }, app.translator.trans('fof-scavenger-hunt.forum.hunt_page.not_running')))));
  }
  content() {
    if (this.notFound) {
      return m("p", {
        className: "HuntPage-notFound"
      }, app.translator.trans('fof-scavenger-hunt.forum.hunt_page.not_found'));
    }
    if (!this.hunt) return null;
    return m("div", {
      className: "HuntPage-content"
    }, m(CollectionView, {
      hunt: this.hunt
    }), m("section", {
      className: "HuntPage-finishers"
    }, m("h3", null, app.translator.trans('fof-scavenger-hunt.forum.hunt_page.first_finishers')), this.loadingFinishers && !this.finishers.length ? m(LoadingIndicator, null) : m(FirstFinishers, {
      completions: this.finishers
    }), this.moreFinishers && m(Button, {
      className: "Button",
      loading: this.loadingFinishers,
      onclick: () => this.loadFinishers()
    }, app.translator.trans('fof-scavenger-hunt.forum.hunt_page.load_more'))));
  }
  loadFinishers() {
    this.loadingFinishers = true;
    app.store.find('scavenger-hunt-completions', {
      filter: {
        hunt: this.hunt.id()
      },
      include: 'user',
      page: {
        offset: this.finishers.length,
        limit: 20
      }
    }).then(completions => {
      this.finishers = [...this.finishers, ...completions];
      this.moreFinishers = !!completions.payload?.links?.next;
    }).finally(() => {
      this.loadingFinishers = false;
      m.redraw();
    });
  }
}
flarum.reg.add('fof-scavenger-hunt', 'forum/components/HuntPage', HuntPage);